import {b,a,f,s,c} from '../authoring.js';

const table=(key,ru,en,columns,rows,lines=[])=>a(key,'table',ru,en,lines,{columns,rows});
const box=(key,ru,en,lines=[])=>a(key,'box',ru,en,lines);
const server=(key,ru,en,lines=[])=>a(key,'server',ru,en,lines);
const app=(lines=[])=>a('app','client','Приложение','Application',lines);
const tree=(key,ru,en,nodes,edges,lines=[])=>a(key,'tree',ru,en,lines,{nodes:nodes.map(([id,label])=>({id,label})),edges});
const wal=(items)=>a('wal','wal','Поток WAL','WAL stream',[],{items});
const queue=(key,ru,en,items,lines=[])=>a(key,'queue',ru,en,lines,{items});
const status=(key,ru,en,lines)=>a(key,'status',ru,en,lines);
// SVG y grows downward; logical point coordinates use an upward y axis.
const points=[{x:20,y:80,label:'A (2,2)'},{x:30,y:70,label:'B (3,3)'},{x:80,y:20,label:'C (8,8)'}];
const space=(regions=[],pts=points)=>a('space','space','Пространство точек','Point space',[],{points:pts,regions});
const hashRows=[['(0,1)','amy'],['(0,2)','lee'],['(0,3)','zoe']];
const hashTable=()=>table('heap','Таблица users','users heap',['TID','name'],hashRows);
const hashBuckets=(items)=>a('hash','buckets','Страницы корзин','Bucket pages',[],{items});
const gistTree=(end='A, B, C')=>tree('gist','GiST: огибающие','GiST: bounding regions',[['root','R: all'],['left','R1: A, B'],['right','R2: C'],['leaf',end]],[['root','left'],['root','right'],['left','leaf']]);
const multiRows=[['1','10','A'],['1','20','B'],['2','10','C'],['2','20','D']];
const multiIndex=(rows=multiRows)=>table('index','Индекс (shop, day)','Index (shop, day)',['shop','day','TID'],rows);
const primary=(lines=[])=>server('primary','Ведущий узел','Primary',lines);
const standby=(lines=[])=>server('standby','Реплика','Standby',lines);
const replicaPositions=(write='0/120',flush='0/120',replay='0/100')=>table('positions','Позиции реплики','Standby positions',['stage','LSN'],[['write',write],['flush',flush],['replay',replay]]);
const triggerSetup=`CREATE TABLE products (id int PRIMARY KEY, name text, price int);
CREATE TABLE price_audit (id int, old_price int, new_price int);`;
const normalizeFunction=`CREATE FUNCTION normalize_product() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.name := lower(NEW.name);
  RETURN NEW;
END;
$$;
CREATE TRIGGER normalize_product_row
BEFORE INSERT ON products
FOR EACH ROW EXECUTE FUNCTION normalize_product();`;
const auditFunction=`CREATE FUNCTION audit_price() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO price_audit VALUES (NEW.id, OLD.price, NEW.price);
  RETURN NULL;
END;
$$;
CREATE TRIGGER audit_price_row
AFTER UPDATE OF price ON products
FOR EACH ROW
WHEN (OLD.price IS DISTINCT FROM NEW.price)
EXECUTE FUNCTION audit_price();`;

export const chapters=[
c({number:51,id:'hash-index',group:7,title:['Hash: адрес по хешу','Hash: locate a bucket'],question:['Как найти точное значение без спуска по дереву?','How can equality search avoid descending a tree?'],next:['Как индекс ищет пересечение областей?','How can an index find overlapping regions?'],docs:['hash-index.html','indexes-types.html'],book:[511,522],steps:[
 s('Нужно найти пользователя с именем amy.','We need the user named amy.',[hashTable()],[],`CREATE TABLE users (name text);
INSERT INTO users VALUES ('amy'), ('lee'), ('zoe');
SELECT * FROM users WHERE name = 'amy';`,'В учебной таблице три строки; адреса на схеме условные. Без подходящего индекса проверяется значение каждой видимой строки. TID обозначает физический адрес версии, а не первичный ключ.','The example has three rows; the displayed addresses are illustrative. Without a suitable index, the visible row values are checked. A TID is a physical tuple address, not a primary key.'),
 s('Hash-индекс хранит хеш значения и адрес строки.','A hash index stores a value hash and tuple address.',[hashTable(),hashBuckets(['bucket 0: h1 → (0,1), (0,3)','bucket 1: h2 → (0,2)','bucket 2: empty'])],[f('heap','hash','build','internal')],`CREATE INDEX users_name_hash ON users USING hash (name);`,'Индекс хранит 32-битный хеш, а не исходное имя. h1 и h2 — условные подписи хешей: распределение по корзинам на схеме поясняет структуру, а не реальные результаты hash-функции.','The index stores a 32-bit hash rather than the original name. h1 and h2 are explanatory hash labels: the bucket layout illustrates the structure, not actual hash-function output.'),
 s('Хеш запроса указывает нужную корзину.','The query hash identifies the bucket.',[app(['name = amy']),hashBuckets(['target: bucket 0','h1 → (0,1)','h1 → (0,3)']),hashTable()],[f('app','hash','hash(amy)','request'),f('hash','heap','candidate TIDs','internal')],`SELECT * FROM users WHERE name = 'amy';`,'Равные значения обязаны иметь одинаковый хеш. Разные значения тоже могут совпасть по хешу, поэтому индекс возвращает кандидатов. Здесь amy и zoe специально показаны как условная коллизия.','Equal values must have the same hash, but distinct values can collide. The index therefore returns candidates. amy and zoe deliberately illustrate a hypothetical collision.'),
 s('Проверка в таблице отбрасывает коллизию zoe.','A heap recheck rejects the colliding value zoe.',[hashBuckets(['h1 → (0,1)','h1 → (0,3)']),table('heap','Проверка кандидатов','Candidate recheck',['name','name = amy'],[['amy','true'],['zoe','false']]),app(['amy'])],[f('hash','heap','recheck =','internal'),f('heap','app','amy','reply')],'','Hash-поиск всегда требует перепроверить равенство по исходному значению. Отдельно проверяется видимость версии по MVCC; совпадение хеша не доказывает ни равенство, ни видимость.','A hash scan rechecks equality using the original value. MVCC visibility is checked separately; a matching hash proves neither equality nor visibility.'),
 s('Переполненная корзина получает цепочку дополнительных страниц.','A full bucket grows an overflow-page chain.',[hashBuckets(['bucket 0 → overflow 1','overflow 1 → overflow 2']),box('cost','Цена роста','Growth cost',[b('Проверить всю цепочку','Scan the whole chain')])],[f('hash','cost','overflow scan','internal')],'','Много одинаковых или неудачно распределённых хешей удлиняет обход. При росте числа корзин PostgreSQL постепенно разделяет существующие корзины; это иной процесс, чем создание overflow-страницы.','Repeated or unevenly distributed hashes make scans longer. PostgreSQL also grows the bucket count through incremental bucket splits; a split is distinct from adding an overflow page.'),
 s('Hash подходит для равенства; порядок и уникальность он не обеспечивает.','Hash serves equality; it provides neither ordering nor uniqueness.',[hashBuckets(['name = amy']),box('limits','Границы метода','Method limits',['= only','one key column','no UNIQUE'])],[],`EXPLAIN SELECT * FROM users WHERE name > 'amy';`,'Предикат name > amy не использует hash как диапазонный доступ. Для диапазонов, ORDER BY и обычной уникальности нужен другой подход, чаще B-tree. На маленькой таблице планировщик вправе выбрать Seq Scan даже для равенства.','A name > amy predicate cannot use hash for range access. Ranges, ORDER BY and ordinary uniqueness need a different approach, usually B-tree. For a tiny table the planner may choose a sequential scan even for equality.')
]}),
c({number:52,id:'gist',group:7,title:['GiST: огибающие области','GiST: bounding regions'],question:['Как отсечь целые ветви пространственного поиска?','How can spatial search prune entire branches?'],next:['Что изменится, если области не перекрываются?','What changes when partitions do not overlap?'],docs:['gist.html','indexes-types.html','functions-geometry.html'],book:[555,588],steps:[
 s('Найдём точки внутри прямоугольника.','Find the points inside a rectangle.',[space([],points)],[],`CREATE TABLE places (id text, p point);
INSERT INTO places VALUES ('A', point(2,2)), ('B', point(3,3)), ('C', point(8,8));
SELECT id FROM places WHERE p <@ box(point(1,1), point(4,4));`,'A и B находятся внутри области от (1,1) до (4,4); C лежит далеко от неё. Для пространственного вопроса полезны свойства областей, а не просто линейный порядок строк.','A and B lie inside the box from (1,1) to (4,4), while C is far away. Spatial predicates benefit from region properties rather than just a linear ordering of rows.'),
 s('Внутренняя запись GiST описывает область целой ветви.','An internal GiST entry summarizes a branch region.',[space([{x:15,y:65,w:20,h:20,label:'R1'},{x:70,y:10,w:20,h:20,label:'R2'}]),gistTree()],[f('space','gist','bounding keys','internal')],`CREATE INDEX places_gist ON places USING gist (p);`,'Показан пространственный вариант GiST: ключи внутренних узлов — огибающие области потомков. В общем случае области могут перекрываться, хотя здесь две группы далеко друг от друга. Фактический разрез дерева зависит от данных.','This is a spatial GiST example: internal keys bound their descendants. Regions can overlap in general, although these two groups are far apart. Actual grouping depends on the data.'),
 s('Область запроса не пересекает дальнюю ветвь: её можно пропустить.','The query misses the distant branch, so that branch is pruned.',[space([{x:10,y:60,w:30,h:30,label:'query'},{x:70,y:10,w:20,h:20,label:'skip'}]),gistTree('A, B')],[f('space','gist','consistent?','request')],`SELECT id FROM places WHERE p <@ box(point(1,1), point(4,4));`,'Узел отвечает, возможен ли хотя бы один результат ниже. Если нет, страницы этой ветви читать незачем. Огибающая допускает лишних кандидатов, но не должна терять настоящие совпадения.','A branch test asks whether a match is possible below it. If not, its pages can be skipped. A bounding key can admit extra candidates but must not discard real matches.'),
 s('Листья дают кандидатов; результат содержит A и B.','Leaf entries yield candidates; the result contains A and B.',[gistTree('A, B'),table('heap','Найденные точки','Matching points',['id','p'],[['A','(2,2)'],['B','(3,3)']]),app(['A, B'])],[f('gist','heap','candidate TIDs','internal'),f('heap','app','A, B','reply')],'','Нужна проверка MVCC-видимости. Дополнительная перепроверка пространственного условия зависит от operator class и флага recheck: нельзя объявлять все GiST-поиски неточными.','MVCC visibility still needs checking. Whether the predicate also needs a recheck depends on the operator class and its recheck flag; not every GiST search is lossy.'),
 s('Новая точка расширяет огибающую выбранной ветви.','A new point expands the selected branch bound.',[space([{x:15,y:55,w:30,h:30,label:'R1 grows'}],[...points,{x:40,y:60,label:'D (4,4)'}]),gistTree('A, B, D')],[f('space','gist','penalty / union','internal')],`INSERT INTO places VALUES ('D', point(4,4));`,'Operator class задаёт, как оценивать расширение области и делить переполненный узел. GiST предоставляет инфраструктуру дерева, конкурентного доступа и WAL, а семантику ключей задаёт класс операторов.','The operator class defines how to estimate enlargement and split a full node. GiST provides tree, concurrency and WAL infrastructure; the operator class defines key semantics.'),
 s('Та же инфраструктура поддерживает и ближайших соседей.','The same infrastructure can support nearest-neighbor search.',[space([{x:15,y:65,w:20,h:20,label:'nearest'}]),gistTree('A first'),app(['A: distance = 0'])],[f('app','gist','ORDER BY distance','request'),f('gist','app','nearest','reply')],`SELECT id FROM places ORDER BY p <-> point(2,2) LIMIT 1;`,'Для point встроенный GiST-класс поддерживает поиск по расстоянию. Это не универсальное обещание для любого типа: доступные условия и операции сортировки определяет operator class.','The built-in GiST point class supports distance ordering. This is not a promise for every type: indexable predicates and ordering operations depend on the operator class.')
]}),
c({number:53,id:'spgist',group:7,title:['SP-GiST: деление пространства','SP-GiST: partition the space'],question:['Как искать по непересекающимся секторам?','How can search follow disjoint partitions?'],next:['А если одна строка содержит много отдельных ключей?','What if one row contains many separate keys?'],docs:['spgist.html','indexes-types.html'],book:[589,611],steps:[
 s('Снова ищем близкие точки, но иначе организуем пространство.','Search the same points with a different spatial organization.',[space()],[],`CREATE TABLE spots (id text, p point);
INSERT INTO spots VALUES ('A', point(2,2)), ('B', point(3,3)), ('C', point(8,8));`,'Значения те же: A(2,2), B(3,3), C(8,8). Сравним структуры без смены задачи, чтобы увидеть отличие от перекрывающихся огибающих GiST.','The values remain A(2,2), B(3,3), C(8,8). Keeping the task fixed makes the structural difference from overlapping GiST bounds visible.'),
 s('Quad-tree делит плоскость на четыре непересекающихся сектора.','A quad-tree divides the plane into four disjoint sectors.',[space([{x:0,y:50,w:50,h:50,label:'SW'},{x:50,y:50,w:50,h:50,label:'SE'},{x:0,y:0,w:50,h:50,label:'NW'},{x:50,y:0,w:50,h:50,label:'NE'}]),tree('sp','SP-GiST','SP-GiST',[['root','center (5,5)'],['sw','SW: A, B'],['se','SE'],['nw','NW'],['ne','NE: C']],[['root','sw'],['root','se'],['root','nw'],['root','ne']])],[f('space','sp','partition','internal')],`CREATE INDEX spots_spgist ON spots USING spgist (p);`,'Для point по умолчанию используется quad_point_ops. Центр (5,5) выбран только для учебного разреза. Реальный индекс сам строит разбиение; SP-GiST также поддерживает другие структуры, например k-d tree.','The default point class is quad_point_ops. The center (5,5) is an explanatory choice; the actual index builds its own partitioning. SP-GiST also supports other structures, such as k-d trees.'),
 s('Запрос в нижнем левом секторе пропускает три другие ветви.','A query in the lower-left sector skips the other three branches.',[space([{x:0,y:50,w:50,h:50,label:'visit SW'},{x:10,y:60,w:30,h:30,label:'query'}]),tree('sp','Ветвь поиска','Search branch',[['root','(5,5)'],['sw','SW'],['a','A'],['b','B']],[['root','sw'],['sw','a'],['sw','b']])],[f('space','sp','p <@ query','request')],`SELECT id FROM spots WHERE p <@ box(point(1,1), point(4,4));`,'Область запроса полностью лежит в одном секторе выбранного разреза. При пересечении границ потребовалось бы посетить несколько ветвей — разбиение не гарантирует одну ветвь для любого запроса.','The query box fits entirely in one partition of this example. A box crossing partition boundaries would require several branches; partitioning does not promise a single path for every query.'),
 s('В выбранном секторе проверяем A и B и получаем две строки.','Check A and B within the chosen sector and return two rows.',[tree('sp','Листья SW','SW leaves',[['sw','SW'],['a','A (2,2)'],['b','B (3,3)']],[['sw','a'],['sw','b']]),table('heap','Результат','Result',['id','p'],[['A','(2,2)'],['B','(3,3)']])],[f('sp','heap','candidate TIDs','internal')],'','Глубина ветвей не обязана быть одинаковой. SP-GiST размещает узлы на дисковых страницах так, чтобы длинный логический путь не превращался в столь же длинную последовательность чтений страниц.','Branches need not have equal depth. SP-GiST maps logical nodes onto disk pages so that a long logical path need not require equally many page reads.'),
 s('Для текстовых префиксов та же идея превращается в radix tree.','For text prefixes, the same idea becomes a radix tree.',[tree('sp','Префиксное дерево','Prefix tree',[['r','ca'],['t','t → cat'],['r2','r → car'],['b','b → cab']],[['r','t'],['r','r2'],['r','b']]),app(['prefix ca'])],[f('app','sp','^@ ca','request')],`CREATE TABLE words (word text);
INSERT INTO words VALUES ('cat'), ('car'), ('cab');
CREATE INDEX words_spgist ON words USING spgist (word);
SELECT word FROM words WHERE word ^@ 'ca';`,'Вместо прямоугольников ветвление задают символы и общие префиксы. Это отдельный пример operator class, а не утверждение, что point-индекс хранит текстовое дерево.','Characters and common prefixes replace geometric partitions. This illustrates a different operator class; a point index does not contain a text radix tree.')
]}),
c({number:54,id:'gin',group:7,title:['GIN: от ключа к строкам','GIN: from a key to rows'],question:['Как найти строки, содержащие нужные элементы?','How can we find rows containing chosen elements?'],next:['Можно ли индексировать лишь сводки групп страниц?','Can an index store summaries of page ranges instead?'],docs:['gin.html','gin.html#GIN-IMPLEMENTATION','indexes-types.html','functions-array.html'],book:[612,641],steps:[
 s('В каждой заметке несколько тегов.','Each note contains several tags.',[table('heap','Заметки','Notes',['id','tags'],[['1','{sql,db}'],['2','{db,ops}'],['3','{sql,ops}']])],[],`CREATE TABLE notes (id int, tags text[]);
INSERT INTO notes VALUES (1, ARRAY['sql','db']), (2, ARRAY['db','ops']), (3, ARRAY['sql','ops']);`,'Задача — искать элементы внутри составного значения. Обычное сравнение массивов целиком не заменяет запрос «содержит оба тега».','The task is to search elements inside a composite value. Comparing entire arrays does not answer whether an array contains both tags.'),
 s('GIN извлекает ключи и связывает каждый со списком адресов.','GIN extracts keys and links each to a posting list.',[table('heap','Заметки','Notes',['id','tags'],[['1','{sql,db}'],['2','{db,ops}'],['3','{sql,ops}']]),a('gin','buckets','Ключи и posting lists','Keys and posting lists',[],{items:['db → TID1, TID2','ops → TID2, TID3','sql → TID1, TID3']})],[f('heap','gin','extract keys','internal')],`CREATE INDEX notes_tags_gin ON notes USING gin (tags);`,'Ключи хранятся в поисковом дереве. Для каждого ключа хранится список TID; большой список выносится в posting tree. Подписи TID1–TID3 обозначают адреса строк с id 1–3.','Keys are held in a search tree. Each key has tuple addresses in a posting list; large postings use a posting tree. TID1–TID3 label the tuple addresses for rows with id 1–3.'),
 s('Для двух обязательных тегов читаем два списка кандидатов.','For two required tags, read two candidate lists.',[app(['tags @> {sql,db}']),a('gin','buckets','Нужные ключи','Required keys',[],{items:['sql → TID1, TID3','db → TID1, TID2']})],[f('app','gin','sql AND db','request')],`SELECT id FROM notes WHERE tags @> ARRAY['sql','db'];`,'Оператор @> требует включения каждого элемента справа. Это условие по двум ключам одного GIN-индекса, а не обязательное использование двух отдельных индексов.','The @> operator requires every element on the right. This is a condition on two keys in one GIN index, not a requirement to use two separate indexes.'),
 s('Пересечение списков оставляет только TID1.','Intersecting the lists leaves only TID1.',[a('gin','buckets','Posting lists','Posting lists',[],{items:['sql: {1,3}','db: {1,2}']}),a('matches','bitmap','Кандидаты','Candidates',['1 AND 1 → 1'],{items:['TID1']}),table('heap','Найденная заметка','Matching note',['id','tags'],[['1','{sql,db}']])],[f('gin','matches','AND','internal'),f('matches','heap','fetch / visibility','internal')],'','После обработки ключей исполнитель получает кандидатов и проверяет видимость строк. Нужность перепроверки самого условия зависит от operator class и конкретного оператора.','After key processing, the executor gets candidates and checks tuple visibility. Whether the predicate itself needs rechecking depends on the operator class and operator.'),
 s('Одна новая строка добавляет адрес сразу к нескольким ключам.','One inserted row adds an address under several keys.',[table('heap','Новая заметка','New note',['id','tags'],[['4','{sql,ops}']]),queue('pending','Pending list','Pending list',['sql → TID4','ops → TID4'])],[f('heap','pending','fastupdate','internal')],`INSERT INTO notes VALUES (4, ARRAY['sql','ops']);`,'При включённом fastupdate GIN может сначала поместить новые записи в pending list, затем объединить их с основной структурой. Чтение учитывает и pending list, и основное дерево.','With fastupdate enabled, GIN can first collect entries in a pending list and later merge them into the main structure. Searches account for both the pending list and the main tree.'),
 s('Очистка переносит накопленные записи в основную структуру.','Cleanup merges pending entries into the main structure.',[queue('pending','Pending list','Pending list',[]),a('gin','buckets','GIN после объединения','GIN after merge',[],{items:['db → TID1, TID2','ops → TID2, TID3, TID4','sql → TID1, TID3, TID4']})],[f('pending','gin','merge','internal')],`VACUUM notes;`,'VACUUM и autovacuum могут выполнять очистку pending list; порог размера тоже запускает её. Отложенная работа ускоряет отдельные записи, но большая pending list повышает цену чтения и последующей очистки.','VACUUM and autovacuum can clean the pending list; its size limit can also trigger cleanup. Deferred work can speed individual writes, but a large pending list makes reads and later cleanup more expensive.')
]}),
c({number:55,id:'brin',group:7,title:['BRIN: сводки диапазонов страниц','BRIN: summarize page ranges'],question:['Как маленький индекс отбрасывает большие части таблицы?','How can a tiny index discard large parts of a table?'],next:['Как несколько ключей упорядочиваются в одном индексе?','How are multiple keys ordered within one index?'],docs:['brin.html','indexes-types.html','sql-createindex.html'],book:[642,669],steps:[
 s('События почти упорядочены по времени поступления.','Events are nearly ordered by arrival time.',[table('heap','Диапазоны страниц','Page ranges',['pages','minute values'],[['0–31','1…100'],['32–63','101…200'],['64–95','201…300']])],[],`CREATE TABLE events_brin (id bigint, minute int);
CREATE INDEX events_minute_brin ON events_brin USING brin (minute)
WITH (pages_per_range = 32);`,'Числа на схеме — учебные физические диапазоны, не вывод реального запуска. BRIN особенно полезен, когда значения коррелируют с расположением строк в таблице.','The numbers are an illustrative physical layout, not a reported execution result. BRIN is especially useful when values correlate with physical row placement.'),
 s('Для каждых 32 страниц minmax-класс хранит границы значений.','For each 32-page range, the minmax class stores value bounds.',[table('heap','Диапазоны страниц','Page ranges',['pages','minute'],[['0–31','1…100'],['32–63','101…200'],['64–95','201…300']]),table('brin','BRIN minmax','BRIN minmax',['range','min','max'],[['0–31','1','100'],['32–63','101','200'],['64–95','201','300']])],[f('heap','brin','summarize','internal')],'','Это не список адресов каждой строки. Другие BRIN operator classes могут хранить иные сводки; здесь показан обычный minmax для целых чисел.','This is not a list of every tuple address. Other BRIN operator classes can store different summaries; this example uses ordinary integer minmax.'),
 s('Условие minute = 150 несовместимо с двумя сводками.','The condition minute = 150 rules out two summaries.',[app(['minute = 150']),table('brin','Проверка сводок','Summary checks',['range','contains 150?'],[['0–31','no'],['32–63','possible'],['64–95','no']])],[f('app','brin','150','request')],`SELECT id FROM events_brin WHERE minute = 150;`,'Значение 150 не входит в [1,100] и [201,300]. Средний диапазон только возможен: наличие числа между min и max не доказывает, что такая строка действительно существует.','150 is outside [1,100] and [201,300]. The middle range is only a candidate: lying between min and max does not prove that a matching row exists.'),
 s('Читаем страницы 32–63 и перепроверяем каждую строку.','Read pages 32–63 and recheck their rows.',[table('brin','Кандидат','Candidate',['range'],[['32–63']]),table('heap','Чтение диапазона','Range scan',['minute','= 150'],[['149','false'],['150','true'],['151','false']]),app(['minute 150'])],[f('brin','heap','lossy bitmap','internal'),f('heap','app','matching rows','reply')],'','BRIN даёт неточный bitmap страниц. Экономия возникает от пропуска других диапазонов; внутри выбранного диапазона исполнитель проверяет условие и MVCC-видимость.','BRIN supplies a lossy bitmap of pages. The saving comes from skipping other ranges; within the selected range, the executor checks the predicate and MVCC visibility.'),
 s('Выброс времени 999 расширяет сводку и ухудшает отсечение.','An outlier at 999 widens a summary and weakens pruning.',[table('heap','Новая строка в старой области','New row in an old range',['pages','new minute'],[['0–31','999']]),table('brin','Расширенная сводка','Expanded summary',['range','min','max'],[['0–31','1','999'],['32–63','101','200']])],[f('heap','brin','expand max','internal')],'','Предположим, новая версия попала в свободное место диапазона 0–31. Теперь запрос minute = 150 должен читать и его, хотя совпадения там может не быть. Физическая корреляция определяет полезность minmax.','Suppose a new tuple lands in free space within pages 0–31. A minute = 150 search must now inspect that range too, even if it has no match. Physical correlation determines minmax effectiveness.'),
 s('Новые диапазоны надо суммировать; меньший диапазон даёт более точные сводки.','New ranges need summaries; smaller ranges provide finer bounds.',[table('brin','Состояние сводок','Summary state',['range','state'],[['0–31','[1,999]'],['32–63','[101,200]'],['96–127',b('без сводки','unsummarized')]]),box('tradeoff','Компромисс','Tradeoff',[b('Меньше страниц в сводке','Fewer pages per summary'),b('Больше записей индекса','More index entries')])],[],`SELECT brin_summarize_new_values('events_minute_brin');`,'Несуммированный диапазон нельзя безопасно отбросить. Для новых диапазонов есть ручная суммаризация, VACUUM и параметр autosummarize. Снижение pages_per_range увеличивает индекс, но может уменьшить лишнее чтение.','An unsummarized range cannot safely be skipped. New ranges can be summarized manually, by VACUUM, or through autosummarize. Smaller pages_per_range increases index size but can reduce extra reads.')
]}),
c({number:56,id:'multicolumn',group:7,title:['Составной индекс и skip scan','Multicolumn index and skip scan'],question:['Почему порядок столбцов меняет объём поиска?','Why does column order change the search range?'],next:['Как объединить результаты отдельных индексов?','How can separate indexes be combined?'],docs:['indexes-multicolumn.html','indexes-ordering.html','sql-explain.html'],book:[523,554],steps:[
 s('Ключ (shop, day) сортируется сначала по shop, затем по day.','The key (shop, day) sorts by shop first, then day.',[multiIndex()],[],`CREATE TABLE sales_index (shop int, day int, amount int);
INSERT INTO sales_index VALUES (1,10,100),(1,20,200),(2,10,300),(2,20,400);
CREATE INDEX sales_shop_day ON sales_index (shop, day);`,'A–D — учебные адреса строк. Ключи идут как (1,10), (1,20), (2,10), (2,20), а не как две независимые отсортированные колонки.','A–D are explanatory tuple-address labels. Keys are ordered (1,10), (1,20), (2,10), (2,20), not as two independently sorted columns.'),
 s('Равенство по shop сразу ограничивает одну группу ключей.','Equality on shop narrows the scan to one key group.',[app(['shop = 2']),multiIndex([['2','10','C'],['2','20','D']])],[f('app','index','seek shop 2','request')],`SELECT * FROM sales_index WHERE shop = 2;`,'Все ключи магазина 2 расположены подряд. Индекс может найти начало группы и закончить обход, когда значение первого ключа сменится.','Shop 2 keys are contiguous. The index can seek to the group start and stop when the leading key changes.'),
 s('Условие day >= 20 сужает выбранную группу до D.','The condition day >= 20 narrows that group to D.',[multiIndex([['2','20','D']]),table('heap','Результат','Result',['shop','day','amount'],[['2','20','400']])],[f('index','heap','TID D','internal')],`SELECT * FROM sales_index WHERE shop = 2 AND day >= 20;`,'Равенство на ведущем ключе и диапазон на следующем ограничивают просматриваемую часть B-tree. Дополнительные условия дальше по ключу не всегда уменьшают диапазон обхода.','Leading equality followed by a range on the next key bounds the B-tree scan. Conditions farther right do not always narrow the scanned index range.'),
 s('Если задан только day, совпадения лежат в разных группах.','With only day specified, matches span several groups.',[multiIndex(),app(['day = 20'])],[f('app','index','day only','request')],`EXPLAIN SELECT * FROM sales_index WHERE day = 20;`,'Строки B и D разделены ключами других дней. Неверно правило «без первого столбца индекс бесполезен»: планировщик может выбрать широкий индексный проход, skip scan или Seq Scan.','B and D are separated by other keys. The rule “an index is useless without its first column” is false: the planner can choose a broad index scan, skip scan, or sequential scan.'),
 s('Skip scan повторяет поиск day = 20 для разных shop.','Skip scan repeats the day = 20 search for different shops.',[queue('seeks','Повторные поиски','Repeated seeks',['shop 1, day 20 → B','shop 2, day 20 → D']),multiIndex([['1','20','B'],['2','20','D']])],[f('seeks','index','reposition','internal')],'','PostgreSQL может подставлять разные значения пропущенного ведущего ключа и заново позиционироваться. Это выгодно лишь при подходящем распределении: мало shop, достаточно пропускаемых страниц. На четырёх строках такой план не обещается.','PostgreSQL can generate values for the missing leading key and reposition the scan. It helps only with a suitable distribution: few shops and enough pages to skip. This four-row example does not promise that plan.'),
 s('Индекс (shop, day) также помогает получить порядок внутри магазина.','The index also provides day order within a shop.',[multiIndex([['2','10','C'],['2','20','D']]),app(['10, 20'])],[f('index','app','ordered rows','reply')],`EXPLAIN SELECT * FROM sales_index WHERE shop = 2 ORDER BY day;`,'B-tree способен отдать строки в нужном порядке, если порядок запроса согласуется с ключами и направлениями. Это может сэкономить Sort, но выбор плана остаётся стоимостным.','A B-tree can supply ordered rows when requested order matches its keys and directions. This can avoid a Sort, but plan choice still depends on estimated cost.')
]}),
c({number:57,id:'bitmap',group:7,title:['Bitmap: собрать адреса, затем читать','Bitmap: collect addresses before fetching'],question:['Как два отдельных индекса помогают одному условию?','How can two separate indexes serve one predicate?'],next:['Можно ли вообще не читать таблицу после поиска в индексе?','Can an index answer without fetching heap tuples?'],docs:['indexes-bitmap-scans.html','using-explain.html'],book:[414,437],steps:[
 s('Нужны оплаченные заказы из магазина 2.','Find paid orders from shop 2.',[table('heap','Заказы','Orders',['id','shop','paid'],[['1','2','true'],['2','1','true'],['3','2','false'],['4','1','false']])],[],`CREATE TABLE orders_bitmap (id int, shop int, paid boolean);
INSERT INTO orders_bitmap VALUES (1,2,true),(2,1,true),(3,2,false),(4,1,false);
CREATE INDEX orders_shop_idx ON orders_bitmap (shop);
CREATE INDEX orders_paid_idx ON orders_bitmap (paid);`,'Показаны два независимых индекса. Для столь маленького набора Seq Scan обычно дешевле; пример объясняет возможный механизм bitmap-плана, а не обещает его выбор.','The indexes are independent. A sequential scan is usually cheaper for this tiny set; the example explains a possible bitmap mechanism rather than promising this plan.'),
 s('Первый индекс отмечает адреса заказов магазина 2.','The first index marks tuple addresses for shop 2.',[box('shop','Индекс shop','shop index',['shop 2 → TID1, TID3']),a('bits','bitmap','Bitmap shop','Shop bitmap',[],{items:['TID1','TID3']})],[f('shop','bits','set bits','internal')],`EXPLAIN SELECT * FROM orders_bitmap WHERE shop = 2 AND paid;`,'Bitmap Index Scan сначала собирает набор физических адресов. В схеме TID1–TID4 обозначают версии строк с соответствующими id. Значения остальных столбцов ещё не получены.','A Bitmap Index Scan first collects physical tuple addresses. TID1–TID4 label tuple versions of the displayed rows. Other column values have not been fetched yet.'),
 s('Второй индекс отмечает оплаченные строки; AND оставляет TID1.','The second index marks paid rows; AND leaves TID1.',[a('shop','bitmap','shop = 2','shop = 2',[],{items:['TID1','TID3']}),a('paid','bitmap','paid = true','paid = true',[],{items:['TID1','TID2']}),a('bits','bitmap','BitmapAnd','BitmapAnd',[],{items:['TID1']})],[f('shop','bits','AND','internal'),f('paid','bits','AND','internal')],'','BitmapAnd пересекает наборы адресов. Для OR возможен BitmapOr. Сначала объединяются кандидаты, затем Bitmap Heap Scan получает строки из таблицы.','BitmapAnd intersects address sets; OR can use BitmapOr. Candidates are combined first, and a Bitmap Heap Scan then fetches table rows.'),
 s('Heap Scan читает нужные страницы в физическом порядке.','The heap scan visits selected pages in physical order.',[a('bits','bitmap','Кандидаты','Candidates',[],{items:['TID1']}),table('heap','Полученная строка','Fetched row',['id','shop','paid'],[['1','2','true']]),app(['id 1'])],[f('bits','heap','page / offset','internal'),f('heap','app','visible match','reply')],'','Порядок ключей исходных индексов теряется. Если запросу нужен ORDER BY, после bitmap-прохода может понадобиться отдельная сортировка.','The original index key order is lost. An ORDER BY query can require a separate sort after a bitmap scan.'),
 s('При нехватке памяти bitmap может помнить страницу целиком.','Under memory pressure, the bitmap can mark a whole page.',[a('bits','bitmap','Неточный bitmap','Lossy bitmap',[],{items:['page 4: all tuples']}),table('heap','Перепроверка страницы 4','Recheck page 4',['tuple','shop','paid'],[['(4,1)','2','true'],['(4,2)','1','true'],['(4,3)','2','false']])],[f('bits','heap','Recheck Cond','internal')],'','Тогда проверяются все строки помеченной страницы. EXPLAIN ANALYZE может показывать exact/lossy heap blocks и строки, удалённые перепроверкой; это объясняет лишнюю работу при том же условии.','The executor then rechecks tuples on the whole marked page. EXPLAIN ANALYZE can report exact/lossy heap blocks and rows removed by recheck, explaining extra work for the same predicate.')
]}),
c({number:58,id:'index-only',group:7,title:['Index Only Scan и INCLUDE','Index Only Scan and INCLUDE'],question:['Почему имя Index Only не гарантирует ноль чтений heap?','Why does Index Only not guarantee zero heap fetches?'],next:['Чем свойства индекса отличаются от его метода доступа?','How do index properties differ from access methods?'],docs:['indexes-index-only-scans.html','storage-vm.html','routine-vacuuming.html'],book:[394,413],steps:[
 s('Запросу нужны id и email, а искать надо по id.','The query needs id and email but searches by id.',[table('heap','Участники','Members',['id','email'],[['7','a@example.org'],['8','b@example.org']])],[],`CREATE TABLE members_cover (id int, email text);
INSERT INTO members_cover VALUES (7,'a@example.org'),(8,'b@example.org');
SELECT email FROM members_cover WHERE id = 7;`,'Индекс только по id нашёл бы адрес, но за email пришлось бы сходить в таблицу. Добавим полезную нагрузку в листовую запись индекса.','An id-only index would locate the tuple but need the heap for email. We can store that payload in the index leaf entry.'),
 s('INCLUDE сохраняет email рядом с поисковым ключом id.','INCLUDE stores email beside the searchable id key.',[table('index','Покрывающий B-tree','Covering B-tree',['key: id','payload: email','TID'],[['7','a@example.org','(4,1)'],['8','b@example.org','(4,2)']])],[],`CREATE UNIQUE INDEX members_cover_idx ON members_cover (id) INCLUDE (email);`,'Поиск и уникальность здесь определяются только id. email хранится для возврата результата и не становится дополнительным поисковым ключом или частью проверки UNIQUE.','Only id guides lookup and uniqueness here. email is stored for returning the result; it is neither an additional search key nor part of UNIQUE checking.'),
 s('Все нужные значения есть, но видимость ещё надо доказать.','All requested values are present, but visibility still needs proof.',[table('index','Кандидат','Candidate',['id','email','TID'],[['7','a@example.org','(4,1)']]),a('vm','bitmap','Visibility map','Visibility map',[],{items:['page 4: all-visible = 1']})],[f('index','vm','page 4','internal')],`EXPLAIN SELECT email FROM members_cover WHERE id = 7;`,'Обычная индексная запись не хранит достаточную MVCC-видимость версии. Проверка all-visible бита страницы позволяет не читать заголовок каждой версии в heap.','An ordinary index entry does not carry sufficient tuple MVCC visibility. The page all-visible bit can avoid reading the heap tuple header.'),
 s('All-visible установлен: email возвращается прямо из индекса.','With all-visible set, return email directly from the index.',[table('index','Индекс','Index',['id','email'],[['7','a@example.org']]),a('vm','bitmap','Visibility map','Visibility map',[],{items:['page 4: 1']}),app(['a@example.org'])],[f('index','vm','check','internal'),f('index','app','email','reply')],'','Табличная страница не нужна именно для этой проверки. Карта видимости всё равно читается; Index Only Scan не означает отсутствие любой работы с памятью или диском.','This lookup does not need the heap page. The visibility map is still consulted; an Index Only Scan does not mean no memory or disk work.'),
 s('Изменение страницы сбрасывает бит: придётся проверить heap.','A page change clears the bit, requiring a heap visibility check.',[table('index','Индекс','Index',['id','email','TID'],[['7','a@example.org','(4,1)']]),a('vm','bitmap','Visibility map','Visibility map',[],{items:['page 4: all-visible = 0']}),table('heap','Heap visibility','Heap visibility',['TID','status'],[['(4,1)',b('проверить снимок','check snapshot')]])],[f('index','vm','check bit','internal'),f('vm','heap','heap fetch','internal')],'','Даже если план по-прежнему называется Index Only Scan, для части строк возможны Heap Fetches. Недавние изменения и незавершённые транзакции влияют на практический выигрыш.','A plan can still be named Index Only Scan while performing Heap Fetches for some rows. Recent changes and open transactions affect the actual benefit.'),
 s('VACUUM может снова отметить страницу как all-visible.','VACUUM can mark the page all-visible again.',[table('heap','Страница 4','Page 4',['state'],[[b('все версии видимы всем','all tuples visible to all')]]),a('vm','bitmap','Visibility map','Visibility map',[],{items:['page 4: all-visible = 1']}),app(['Heap Fetches: 0?'])],[f('heap','vm','VACUUM','internal')],`VACUUM members_cover;
EXPLAIN (ANALYZE, BUFFERS) SELECT email FROM members_cover WHERE id = 7;`,'VACUUM устанавливает бит лишь при выполнении условий видимости. Ноль Heap Fetches — возможный результат, который надо проверять, а не гарантировать одним INCLUDE. Широкий payload увеличивает индекс.','VACUUM sets the bit only when visibility conditions permit. Zero Heap Fetches is a result to verify, not a guarantee of INCLUDE. Wide payload values also enlarge the index.')
]}),
c({number:59,id:'index-properties',group:7,title:['UNIQUE, выражение и частичный индекс','UNIQUE, expression and partial indexes'],question:['Это новые методы индекса или свойства привычного дерева?','Are these new access methods or properties of familiar indexes?'],next:['Как база выполняет действие автоматически при изменении строки?','How does the database run an action when a row changes?'],docs:['indexes-unique.html','indexes-expressional.html','indexes-partial.html','sql-createindex.html'],book:[523,554],steps:[
 s('B-tree задаёт устройство, а UNIQUE — дополнительное правило.','B-tree is the structure; UNIQUE adds a rule.',[table('heap','Аккаунты','Accounts',['id','email','active'],[['1','Ada@example.org','true'],['2','ada@example.org','false']])],[],`CREATE TABLE accounts_idx (id int, email text, active boolean);
INSERT INTO accounts_idx VALUES (1,'Ada@example.org',true),(2,'ada@example.org',false);`,'Метод доступа, выражение ключа, предикат и уникальность — разные оси настройки. Их можно сочетать в одной команде CREATE INDEX.','Access method, key expression, predicate and uniqueness are separate choices. They can be combined in one CREATE INDEX command.'),
 s('Выражение lower(email) превращает регистр в одинаковый ключ.','The expression lower(email) maps case variants to the same key.',[table('heap','Исходные значения','Source values',['id','email'],[['1','Ada@example.org'],['2','ada@example.org']]),table('index','Ключ lower(email)','Key lower(email)',['id','key'],[['1','ada@example.org'],['2','ada@example.org']])],[f('heap','index','lower(email)','internal')],`CREATE INDEX accounts_email_lower ON accounts_idx (lower(email));
SELECT id FROM accounts_idx WHERE lower(email) = 'ada@example.org';`,'Индекс хранит вычисленный ключ. Выражение запроса должно подходить к индексному выражению; добавление индекса не делает любые сравнения текста нечувствительными к регистру.','The index stores the computed key. A query must use a matching expression; creating the index does not make every text comparison case-insensitive.'),
 s('Частичный индекс включает только active = true.','A partial index includes only active = true rows.',[table('heap','Аккаунты','Accounts',['id','active'],[['1','true'],['2','false']]),table('index','Только активные','Active entries only',['id','key'],[['1','ada@example.org']])],[f('heap','index','WHERE active','internal')],`CREATE UNIQUE INDEX accounts_active_email ON accounts_idx (lower(email)) WHERE active;`,'Неактивная строка 2 не участвует в этом индексе. Уникальность действует среди включённых строк по lower(email); конфликт регистра для двух активных аккаунтов будет запрещён.','Inactive row 2 is absent from this index. Uniqueness applies to lower(email) among included rows; two active case variants would conflict.'),
 s('Активация второго аккаунта нарушила бы уникальность ключа.','Activating the second account would violate key uniqueness.',[table('index','Занятый ключ','Existing key',['key','id'],[['ada@example.org','1']]),box('update','Попытка UPDATE','UPDATE attempt',['id 2 → active true']),status('error','Ошибка','Error',['23505 unique_violation'])],[f('update','index','insert key','request'),f('index','error','duplicate','reply')],`UPDATE accounts_idx SET active = true WHERE id = 2;`,'Команда показана как намеренная ошибка: вся её работа откатывается. Индекс одновременно помогает поиску и обеспечивает правило для новых записей ключа.','This statement intentionally raises an error and its effects roll back. The index both supports lookup and enforces the rule for new key entries.'),
 s('Запрос должен доказывать предикат частичного индекса.','A query must imply the partial-index predicate.',[app(['lower(email) = ...','active = true']),table('index','Частичный индекс','Partial index',['key','id'],[['ada@example.org','1']])],[f('app','index','predicate implied','request')],`EXPLAIN SELECT id FROM accounts_idx WHERE active AND lower(email) = 'ada@example.org';`,'Без active индекс не содержит всех подходящих строк. Планировщик проверяет применимость на этапе планирования; неизвестные параметры generic plan не всегда позволяют доказать нужный предикат.','Without active, the index lacks some possible matches. Applicability is proved at planning time; unknown generic-plan parameters do not always prove the required predicate.'),
 s('NULL по умолчанию не равен другому NULL; это можно изменить.','NULLs are distinct by default; the uniqueness rule can change.',[table('nulls','Уникальность NULL','NULL uniqueness',['option','NULL, NULL'],[['default',b('разрешено','allowed')],['NULLS NOT DISTINCT',b('конфликт','conflict')]])],[],`CREATE TABLE invite_keys (code text);
CREATE UNIQUE INDEX invite_keys_one_null ON invite_keys (code) NULLS NOT DISTINCT;`,'Этот индекс допускает только один NULL. Это настройка проверки уникальности, а не изменение общей SQL-семантики сравнения NULL и не отдельный метод доступа.','This index permits only one NULL. It changes uniqueness checking, not general SQL NULL comparison semantics, and is not a separate access method.')
]}),
c({number:60,id:'triggers',group:8,title:['Строковые BEFORE и AFTER','Row-level BEFORE and AFTER'],question:['На каком этапе триггер видит OLD и NEW?','When does a trigger see OLD and NEW?'],next:['Что делать один раз для всей команды, а не каждой строки?','What should run once per statement rather than per row?'],docs:['trigger-definition.html','plpgsql-trigger.html','sql-createtrigger.html'],book:[],steps:[
 s('Приложение вставляет товар с именем BOOK.','The application inserts a product named BOOK.',[app(['INSERT (1, BOOK, 100)'])],[],triggerSetup,'В этой главе products — основная таблица, price_audit — журнал изменений. Триггер выполняет функцию внутри той же транзакции, что и вызвавшая его команда.','In this chapter products is the main table and price_audit records changes. A trigger function runs inside the same transaction as its triggering statement.'),
 s('BEFORE INSERT получает NEW до записи версии в таблицу.','BEFORE INSERT receives NEW before the tuple is stored.',[app(['INSERT (1, BOOK, 100)']),box('before','BEFORE ROW','BEFORE ROW',['NEW.name = BOOK']),table('heap','products','products',['id','name','price'],[])],[f('app','before','NEW','request')],normalizeFunction,'Функция normalize_product возвращает NEW с именем в нижнем регистре. Это пример изменения входящей строки; для INSERT нет OLD, а для DELETE нет NEW.','normalize_product returns NEW with a lowercase name. This illustrates modifying the incoming row; INSERT has no OLD and DELETE has no NEW.'),
 s('Возвращённый NEW содержит book; именно он попадает в таблицу.','Returned NEW contains book, which is the value stored.',[box('before','BEFORE ROW','BEFORE ROW',['NEW.name = book','RETURN NEW']),table('heap','products','products',['id','name','price'],[['1','book','100']]),app(['INSERT 0 1'])],[f('before','heap','store NEW','internal'),f('heap','app','success','reply')],`INSERT INTO products VALUES (1,'BOOK',100);`,'RETURN NULL из BEFORE ROW пропустил бы операцию для этой строки. Успех INSERT ещё не означает COMMIT, если команда выполняется в явно открытой транзакции.','RETURN NULL from a BEFORE ROW trigger would skip that row operation. Successful INSERT does not imply COMMIT if it runs inside an explicit transaction.'),
 s('AFTER UPDATE получает старую цену 100 и новую 120.','AFTER UPDATE receives the old price 100 and new price 120.',[table('heap','products','products',['id','name','price'],[['1','book','120']]),queue('after','Очередь AFTER ROW','AFTER ROW queue',['OLD.price = 100','NEW.price = 120'])],[f('heap','after','queue event','internal')],`${auditFunction}
BEGIN;
UPDATE products SET price = 120 WHERE id = 1;`,'AFTER ROW события выполняются к концу команды. Условие WHEN здесь добавляет событие только при фактическом изменении цены. RETURN NULL из AFTER не отменяет обновление строки.','AFTER ROW events run at the end of the statement. This WHEN condition queues an event only when the price changes. RETURN NULL from AFTER does not cancel the row update.'),
 s('AFTER-триггер записывает одну строку аудита.','The AFTER trigger inserts one audit row.',[table('heap','products','products',['id','price'],[['1','120']]),queue('after','AFTER ROW','AFTER ROW',['id 1: 100 → 120']),table('audit','price_audit','price_audit',['id','old_price','new_price'],[['1','100','120']])],[f('after','audit','INSERT audit','internal')],`SELECT * FROM price_audit;`,'Внутри этой транзакции видны и изменение цены, и запись аудита. AFTER означает после операции, но не после фиксации и не отдельную фоновую задачу.','This transaction sees both the new price and its audit row. AFTER means after the operation, not after commit and not a separate background job.'),
 s('ROLLBACK отменяет и цену 120, и строку аудита.','ROLLBACK removes both the price change and its audit row.',[table('heap','products','products',['id','price'],[['1','100']]),table('audit','price_audit','price_audit',['id','old_price','new_price'],[]),app(['ROLLBACK'])],[f('app','heap','rollback','request'),f('app','audit','rollback','internal')],`ROLLBACK;`,'Обычные записи, сделанные функцией триггера в PostgreSQL, участвуют в той же атомарности. Внешние эффекты вне транзакции базы нельзя автоматически считать обратимыми.','Ordinary PostgreSQL writes performed by the trigger participate in the same atomicity. Effects outside the database transaction cannot automatically be assumed reversible.'),
 s('Несколько однотипных триггеров выполняются по имени.','Multiple triggers of the same kind run in name order.',[queue('order','Порядок BEFORE INSERT','BEFORE INSERT order',['a_validate','b_normalize','c_enrich']),box('new','Текущий NEW','Current NEW',[b('Передаётся следующему','Passed to the next')])],[f('order','new','NEW pipeline','internal')],'','Для одинаковых события, времени и уровня порядок определяется именами триггеров. Следующий BEFORE получает строку после предыдущего; RETURN NULL останавливает обработку этой строки.','For the same event, timing and level, trigger names determine execution order. Each BEFORE receives the row returned by its predecessor; RETURN NULL stops processing that row.')
]}),
c({number:61,id:'statement-triggers',group:8,title:['Команда целиком и transition tables','Statement triggers and transition tables'],question:['Как один триггер видит все изменённые строки?','How can one trigger inspect all changed rows?'],next:['Как изменить данные через представление?','How can a view accept data changes?'],docs:['trigger-definition.html','sql-createtrigger.html','plpgsql-trigger.html'],book:[],steps:[
 s('Одна команда повышает цену двух товаров.','One statement raises the price of two products.',[table('heap','products','products',['id','price'],[['1','100'],['2','200']])],[],`CREATE TABLE bulk_products (id int PRIMARY KEY, price int);
CREATE TABLE bulk_audit (changed_rows bigint);
INSERT INTO bulk_products VALUES (1,100),(2,200);`,'Сравним количество вызовов: ROW-триггер работает для каждой затронутой строки, STATEMENT-триггер — один раз для команды.','Compare invocation counts: a ROW trigger runs for each affected row, while a STATEMENT trigger runs once for the statement.'),
 s('AFTER STATEMENT с NEW TABLE получает набор новых версий.','AFTER STATEMENT with NEW TABLE receives the changed row set.',[table('heap','bulk_products','bulk_products',['id','price'],[['1','110'],['2','210']]),table('transition','changed: NEW TABLE','changed: NEW TABLE',['id','price'],[['1','110'],['2','210']])],[f('heap','transition','collect NEW rows','internal')],`CREATE FUNCTION count_price_changes() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO bulk_audit SELECT count(*) FROM changed;
  RETURN NULL;
END;
$$;
CREATE TRIGGER count_price_changes_stmt
AFTER UPDATE ON bulk_products
REFERENCING NEW TABLE AS changed
FOR EACH STATEMENT EXECUTE FUNCTION count_price_changes();
UPDATE bulk_products SET price = price + 10;`,'Transition relation changed доступна функции как набор строк этой команды. Здесь нужен обычный AFTER-триггер, не отложенный constraint trigger.','The changed transition relation exposes this statement’s row set to the function. This is an ordinary AFTER trigger, not a deferred constraint trigger.'),
 s('Две строки изменены, а функция вызывается один раз.','Two rows change, but the function is called once.',[table('transition','changed','changed',['id','price'],[['1','110'],['2','210']]),box('trigger','AFTER STATEMENT','AFTER STATEMENT',['count(*) = 2','calls = 1']),table('audit','bulk_audit','bulk_audit',['changed_rows'],[['2']])],[f('transition','trigger','whole set','internal'),f('trigger','audit','INSERT 2','internal')],`SELECT * FROM bulk_audit;`,'Команда не делает два вызова count_price_changes. Функция агрегирует уже собранный набор и записывает одну строку с числом 2.','The statement does not call count_price_changes twice. The function aggregates the collected set and inserts one audit row containing 2.'),
 s('Команда без совпадений всё равно вызывает STATEMENT-триггер.','A statement affecting no rows still fires its STATEMENT trigger.',[table('transition','changed','changed',['id','price'],[]),box('trigger','AFTER STATEMENT','AFTER STATEMENT',['count(*) = 0','calls = 1']),table('audit','bulk_audit','bulk_audit',['changed_rows'],[['2'],['0']])],[f('transition','trigger','empty set','internal'),f('trigger','audit','INSERT 0','internal')],`UPDATE bulk_products SET price = price + 10 WHERE id = 999;`,'Отсутствие строк не отменяет событие команды. ROW-триггер в таком случае не вызвался бы ни разу.','The statement event still occurs when no rows match. A ROW trigger would have zero invocations in this case.'),
 s('OLD TABLE и NEW TABLE позволяют сравнить наборы до и после.','OLD TABLE and NEW TABLE allow set-wise before/after comparison.',[table('old','OLD TABLE','OLD TABLE',['id','price'],[['1','100'],['2','200']]),table('transition','NEW TABLE','NEW TABLE',['id','price'],[['1','110'],['2','210']]),box('aggregate','Разница команды','Statement difference',['sum(new-old) = 20'])],[f('old','aggregate','old set','internal'),f('transition','aggregate','new set','internal')],'','Здесь показаны наборы первой команды повышения. У строк есть ключ id, по которому функция могла бы связать наборы. Порядок строк сам по себе не даёт соответствия OLD и NEW.','These are the row sets from the first price update. A function could join them on id; row order alone does not pair OLD and NEW rows.'),
 s('TRUNCATE имеет только уровень STATEMENT.','TRUNCATE supports only STATEMENT triggers.',[box('command','TRUNCATE','TRUNCATE',['all rows']),queue('triggers','События','Events',['BEFORE STATEMENT','TRUNCATE','AFTER STATEMENT'])],[f('command','triggers','statement event','request')],`CREATE TABLE scratch_products (id int);
TRUNCATE scratch_products;`,'TRUNCATE не проходит последовательно по строкам как DELETE, поэтому отдельного ROW-триггера для него нет. Это различие важно при проектировании аудита.','TRUNCATE does not delete rows one by one like DELETE, so it has no ROW trigger. That distinction matters when designing an audit trail.')
]}),
c({number:62,id:'view-triggers',group:8,title:['INSTEAD OF: запись через view','INSTEAD OF: write through a view'],question:['Кто превращает изменение представления в запись базовых таблиц?','Who turns a view change into base-table writes?'],next:['Можно ли проверить правило только в конце транзакции?','Can a rule be checked at transaction end?'],docs:['trigger-definition.html','sql-createtrigger.html','plpgsql-trigger.html','sql-createview.html'],book:[],steps:[
 s('Представление показывает строку из двух базовых таблиц.','A view presents a row from two base tables.',[table('view','catalog_view','catalog_view',['id','name','price'],[['1','book','100']])],[],`CREATE TABLE catalog_names (id int PRIMARY KEY, name text);
CREATE TABLE catalog_prices (id int PRIMARY KEY, price int);
INSERT INTO catalog_names VALUES (1,'book');
INSERT INTO catalog_prices VALUES (1,100);
CREATE VIEW catalog_view AS
SELECT n.id, n.name, p.price FROM catalog_names n JOIN catalog_prices p USING (id);`,'Этот join-view не является простым автоматически обновляемым представлением. Для INSERT объясним явное правило записи, заданное INSTEAD OF-триггером.','This join view is not a simple automatically updatable view. We will define its INSERT behavior explicitly using an INSTEAD OF trigger.'),
 s('INSTEAD OF INSERT получает новую строку представления.','INSTEAD OF INSERT receives the new view row.',[app(['INSERT (2, pen, 50)']),table('view','Новый ряд view','New view row',['id','name','price'],[['2','pen','50']]),box('trigger','INSTEAD OF ROW','INSTEAD OF ROW',['NEW.id = 2'])],[f('app','view','INSERT','request'),f('view','trigger','NEW','internal')],`CREATE FUNCTION insert_catalog() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO catalog_names VALUES (NEW.id, NEW.name);
  INSERT INTO catalog_prices VALUES (NEW.id, NEW.price);
  RETURN NEW;
END;
$$;
CREATE TRIGGER catalog_insert
INSTEAD OF INSERT ON catalog_view
FOR EACH ROW EXECUTE FUNCTION insert_catalog();`,'Функция сама решает, какие базовые таблицы менять. INSTEAD OF на представлении выполняется для каждой строки; отдельной физической строки view не создаётся.','The function decides which base tables to modify. A view INSTEAD OF trigger runs per row; it does not create a separately stored view tuple.'),
 s('Один INSERT во view создаёт по строке в обеих таблицах.','One view INSERT creates a row in each base table.',[box('trigger','INSTEAD OF ROW','INSTEAD OF ROW',['id 2']),table('names','catalog_names','catalog_names',['id','name'],[['1','book'],['2','pen']]),table('prices','catalog_prices','catalog_prices',['id','price'],[['1','100'],['2','50']])],[f('trigger','names','INSERT name','internal'),f('trigger','prices','INSERT price','internal')],`INSERT INTO catalog_view VALUES (2,'pen',50);`,'Обе записи входят в одну транзакцию. Ошибка второй вставки откатила бы и первую — приложение не должно получить наполовину записанную строку view.','Both writes belong to the same transaction. If the second insert fails, the first is rolled back too; the view row should not be half-written.'),
 s('Повторное чтение view собирает строку из базовых таблиц.','Reading the view reconstructs the row from the base tables.',[table('names','catalog_names','catalog_names',['id','name'],[['2','pen']]),table('prices','catalog_prices','catalog_prices',['id','price'],[['2','50']]),table('view','catalog_view','catalog_view',['id','name','price'],[['2','pen','50']])],[f('names','view','JOIN id','internal'),f('prices','view','JOIN id','internal')],`SELECT * FROM catalog_view WHERE id = 2;`,'Обычное view хранит определение запроса, а не его результат. RETURN NEW сообщает об обработанной строке и позволяет корректно работать INSERT RETURNING.','An ordinary view stores a query definition, not its result. RETURN NEW reports the handled row and supports INSERT RETURNING.'),
 s('Для UPDATE и DELETE нужны собственные правила обработки.','UPDATE and DELETE need their own handling rules.',[table('view','catalog_view','catalog_view',['id','name','price'],[['2','pen','50']]),box('events','Определённые события','Defined events',['INSERT: handled','UPDATE: no handler','DELETE: no handler'])],[],'','Мы определили только INSERT. Наличие этого триггера не добавляет автоматически смысл обновлению и удалению. Для простых view PostgreSQL часто умеет преобразовывать записи без INSTEAD OF-триггеров.','Only INSERT was defined here. That trigger does not automatically supply UPDATE or DELETE semantics. PostgreSQL can rewrite writes to many simple views without INSTEAD OF triggers.')
]}),
c({number:63,id:'deferred-triggers',group:8,title:['Отложенная проверка ограничения','Deferred constraint checking'],question:['Как разрешить временное нарушение внутри транзакции?','How can a transaction temporarily violate a rule?'],next:['Как WAL переносит эти изменения на другой сервер?','How does WAL carry these changes to another server?'],docs:['sql-createtrigger.html','sql-set-constraints.html','trigger-definition.html','sql-createtable.html'],book:[],steps:[
 s('Сначала вставим ребёнка, затем родителя в той же транзакции.','Insert a child first, then its parent in the same transaction.',[table('parents','Родители','Parents',['id'],[]),table('children','Потомки','Children',['id','parent_id'],[])],[],`CREATE TABLE deferred_parents (id int PRIMARY KEY);
CREATE TABLE deferred_children (
  id int PRIMARY KEY,
  parent_id int REFERENCES deferred_parents(id) DEFERRABLE INITIALLY DEFERRED
);`,'Внешний ключ — удобный рабочий пример встроенной отложенной проверки. Обычно лучше объявить ограничение, чем писать собственный триггер для стандартного правила целостности.','A foreign key is a practical example of built-in deferred checking. A declared constraint is generally preferable to a custom trigger for a standard integrity rule.'),
 s('INSERT ребёнка ставит проверку в очередь, не отклоняя команду.','The child INSERT queues a check instead of rejecting the statement.',[table('children','Потомки','Children',['id','parent_id'],[['10','1']]),table('parents','Родители','Parents',['id'],[]),queue('checks','Отложенная проверка','Deferred check',['child 10 → parent 1'])],[f('children','checks','queue check','internal')],`BEGIN;
INSERT INTO deferred_children VALUES (10,1);`,'К концу этой команды родителя ещё нет. INITIALLY DEFERRED позволяет отложить проверку до конца транзакции; данные пока не зафиксированы.','At this statement’s end the parent is still absent. INITIALLY DEFERRED postpones the check until transaction end; the data is not committed yet.'),
 s('Следующая команда создаёт родителя 1.','The next statement creates parent 1.',[table('children','Потомки','Children',['id','parent_id'],[['10','1']]),table('parents','Родители','Parents',['id'],[['1']]),queue('checks','Отложенная проверка','Deferred check',['child 10 → parent 1'])],[f('parents','checks','parent now exists','internal')],`INSERT INTO deferred_parents VALUES (1);`,'Ограничение оценивает итоговое состояние, когда приходит момент проверки. Промежуточная последовательность команд допустима, если к проверке правило выполнено.','The constraint checks the state when its check runs. The intermediate statement order is allowed if the rule holds at that point.'),
 s('COMMIT запускает очередь и успешно находит родителя.','COMMIT runs the queued check and finds the parent.',[queue('checks','Проверка FK','FK check',['10 → 1: found']),table('parents','Родители','Parents',['id'],[['1']]),app(['COMMIT'])],[f('checks','parents','lookup 1','internal'),f('parents','app','constraint passes','reply')],`COMMIT;`,'При успешной проверке транзакция может зафиксироваться. Можно запустить такую проверку раньше с SET CONSTRAINTS ALL IMMEDIATE: она также проверит уже накопленные события.','After a successful check the transaction can commit. SET CONSTRAINTS ALL IMMEDIATE can force the check earlier and also checks already queued events.'),
 s('Без родителя 2 ошибка возникает на COMMIT.','With parent 2 missing, the error occurs at COMMIT.',[table('children','Незавершённая вставка','Uncommitted insert',['id','parent_id'],[['11','2']]),queue('checks','Проверка FK','FK check',['11 → 2: missing']),status('error','Ошибка фиксации','Commit error',['23503 foreign_key_violation'])],[f('checks','error','reject commit','reply')],`BEGIN;
INSERT INTO deferred_children VALUES (11,2);
COMMIT;`,'Этот намеренно неуспешный пример не оставляет ребёнка 11 в зафиксированных данных. Отложить проверку не означает отключить её.','This intentionally failing example does not leave child 11 committed. Deferring a check does not disable it.'),
 s('Собственный constraint trigger тоже может ждать конца транзакции.','A custom constraint trigger can also wait until transaction end.',[queue('checks','AFTER ROW события','AFTER ROW events',['event 1','event 2']),box('timing','Момент запуска','Firing point',['DEFERRABLE','INITIALLY DEFERRED'])],[f('checks','timing','at transaction end','internal')],'','CREATE CONSTRAINT TRIGGER требует AFTER ROW на обычной таблице. Отложенная функция должна проверять нужное итоговое состояние; WHEN оценивается при событии, а не откладывается вместе с вызовом.','CREATE CONSTRAINT TRIGGER requires AFTER ROW on a plain table. The deferred function must check the intended final state; its WHEN condition is evaluated at event time, not deferred with the call.')
]}),
c({number:64,id:'physical-replication',group:9,title:['Физическая репликация по WAL','Physical replication through WAL'],question:['Как изменение одной страницы доходит до другого сервера?','How does a page change reach another server?'],next:['На каком этапе COMMIT должен отвечать приложению?','At which stage should COMMIT acknowledge the application?'],docs:['warm-standby.html','hot-standby.html','monitoring-stats.html#MONITORING-PG-STAT-REPLICATION-VIEW'],book:[211,233],steps:[
 s('Ведущий узел принимает записи, реплика восстанавливает его WAL.','The primary accepts writes; the standby replays its WAL.',[primary(['balance = 100'])],[],`SELECT pg_is_in_recovery();`,'На обычном ведущем узле pg_is_in_recovery() возвращает false. Физическая standby начинает с базовой копии и продолжает восстановление по WAL; это не независимый второй писатель.','On an ordinary primary pg_is_in_recovery() returns false. A physical standby starts from a base backup and continues recovery from WAL; it is not an independent second writer.'),
 s('UPDATE создаёт WAL изменений ещё до фиксации транзакции.','UPDATE generates change WAL before the transaction commits.',[app(['UPDATE: 100 → 80']),primary(['uncommitted balance = 80']),wal(['0/120: UPDATE page 4'])],[f('app','primary','UPDATE','request'),f('primary','wal','WAL record','internal')],`CREATE TABLE replica_account (id int PRIMARY KEY, balance int);
INSERT INTO replica_account VALUES (1,100);
BEGIN;
UPDATE replica_account SET balance = 80 WHERE id = 1;`,'Все LSN в этой главе — учебные позиции. Передача WAL не ограничена завершёнными транзакциями: запись изменения страницы может стать доступной потоку до COMMIT.','All LSN values in this chapter are illustrative positions. WAL shipping is not limited to completed transactions: a page-change record can become available before COMMIT.'),
 s('WAL sender передаёт запись, WAL receiver принимает её.','The WAL sender transmits a record to the WAL receiver.',[primary(['walsender']),wal(['0/120: UPDATE page 4']),standby(['walreceiver','received: 0/120'])],[f('primary','wal','flushed WAL','internal'),f('wal','standby','stream','sync')],'','Streaming передаёт доступный WAL, не ожидая заполнения сегмента. Процессы walsender и walreceiver отвечают за транспорт; получение байтов ещё не делает транзакцию видимой запросам.','Streaming sends available WAL without waiting for a full segment. walsender and walreceiver handle transport; receiving bytes does not make the transaction visible to queries.'),
 s('COMMIT добавляет запись фиксации с позицией 0/140.','COMMIT adds its commit record at position 0/140.',[primary(['local flush: 0/140']),wal(['0/120: UPDATE','0/140: COMMIT']),standby(['write: 0/140'])],[f('primary','wal','COMMIT record','internal'),f('wal','standby','receive / write','sync')],`COMMIT;`,'При обычном synchronous_commit=on без настроенных синхронных standby ответ ждёт локальный flush WAL. Физические страницы данных не обязаны уже быть записаны на диск.','With ordinary synchronous_commit=on and no configured synchronous standbys, acknowledgment waits for local WAL flush. The data pages themselves need not have reached disk.'),
 s('Реплика сохранила WAL, но пока не применила COMMIT.','The standby has flushed WAL but not replayed COMMIT yet.',[standby(['visible balance = 100']),replicaPositions('0/140','0/140','0/120'),app(['SELECT → 100'])],[f('app','standby','SELECT','request'),f('standby','app','100','reply')],`SELECT write_lsn, flush_lsn, replay_lsn FROM pg_stat_replication;`,'Этот запрос мониторинга выполняется на primary. В примере write и flush достигли 0/140, а replay — только 0/120. Изменения ещё не видны новому читателю standby, несмотря на сохранённый WAL.','Run this monitoring query on the primary. Here write and flush are at 0/140 while replay is only at 0/120. A new standby reader still cannot see the change even though the WAL is durable.'),
 s('После replay COMMIT новый снимок на реплике видит 80.','After COMMIT replay, a new standby snapshot sees 80.',[standby(['visible balance = 80']),replicaPositions('0/140','0/140','0/140'),app(['SELECT → 80'])],[f('standby','positions','replay commit','internal'),f('standby','app','80','reply')],`SELECT pg_last_wal_replay_lsn();
SELECT balance FROM replica_account WHERE id = 1;`,'Эти запросы выполняются на standby. Видимость появляется для новых снимков после replay записи фиксации; уже открытый Repeatable Read сохраняет свой прежний снимок.','Run these queries on the standby. New snapshots can see the transaction once its commit record is replayed; an existing Repeatable Read snapshot retains its previous view.'),
 s('Асинхронный ответ primary может опередить реплику.','An asynchronous primary acknowledgment can precede standby replay.',[primary(['COMMIT acknowledged']),standby(['replay still behind']),box('gap','Окно отставания','Lag window',[b('Чтение может быть старым','Reads can be stale'),b('Failover может терять WAL','Failover can lose WAL')])],[f('primary','gap','ack before replica','internal')],'','Streaming по умолчанию асинхронный. При потере primary часть уже подтверждённых транзакций может отсутствовать у выбранной standby. Следующая глава меняет именно момент подтверждения.','Streaming is asynchronous by default. If the primary is lost, the chosen standby may lack some acknowledged transactions. The next chapter changes the acknowledgment point.')
]}),
c({number:65,id:'sync-replication',group:9,title:['Синхронность: чего ждёт COMMIT','Synchronous replication: what COMMIT waits for'],question:['Получено, сохранено и применено — одинаковые гарантии?','Are received, durable and replayed the same guarantee?'],next:['Куда приложению отправлять чтения и транзакции?','Where should applications send reads and transactions?'],docs:['runtime-config-wal.html#GUC-SYNCHRONOUS-COMMIT','warm-standby.html#SYNCHRONOUS-REPLICATION','monitoring-stats.html#MONITORING-PG-STAT-REPLICATION-VIEW'],book:[],steps:[
 s('Без выбранных синхронных реплик on ждёт только локальный flush.','Without selected synchronous standbys, on waits for local flush only.',[app(['COMMIT']),primary(['local flush: 0/140']),standby(['replay: 0/100'])],[f('app','primary','COMMIT','request'),f('primary','app','OK','reply')],`SHOW synchronous_commit;
SHOW synchronous_standby_names;`,'Предположим, synchronous_commit=on и synchronous_standby_names пуст. Имя on само по себе не включает ожидание реплик: сначала надо выбрать синхронных участников.','Assume synchronous_commit=on and an empty synchronous_standby_names. The name on alone does not make COMMIT wait for replicas; synchronous participants must be configured.'),
 s('Теперь COMMIT ждёт подтверждение выбранной реплики s1.','Now COMMIT waits for the selected standby s1.',[primary(['on: waiting for s1']),standby(['application_name = s1']),queue('wait','Ожидание COMMIT','COMMIT wait',['FIRST 1 (s1, s2)'])],[f('primary','standby','WAL to 0/140','sync'),f('standby','wait','ack needed','wait')],'','В учебной конфигурации FIRST 1 (s1,s2) выбирает одну standby по приоритету; ANY 1 (s1,s2) ждёт любую одну. Далее сравним три альтернативных запуска изменения balance 100 → 80 из одного исходного состояния; LSN условные.','The illustrative FIRST 1 (s1,s2) configuration selects one standby by priority; ANY 1 (s1,s2) waits for any one. Next compare three alternative runs of balance 100 → 80 from the same initial state; LSN values are illustrative.'),
 s('Тот же COMMIT в варианте remote_write ждёт записи WAL в файловую систему реплики.','The same COMMIT in the remote_write alternative waits for the standby filesystem write.',[primary(['local flush: 0/140']),replicaPositions('0/140','0/120','0/100'),app(['remote_write: OK'])],[f('positions','primary','write ack','sync'),f('primary','app','OK','reply')],`-- Alternative run from the same initial state: balance = 100.
-- LSN 0/140 is illustrative; these are not consecutive commits.
BEGIN;
SET LOCAL synchronous_commit = 'remote_write';
UPDATE replica_account SET balance = 80 WHERE id = 1;
COMMIT;`,'Схема показывает ожидание записывающей транзакции. Реплика может пережить падение процесса PostgreSQL, но WAL не обязан пережить сбой её ОС. Также ожидается локальный flush на primary.','The diagram shows a writing transaction’s wait. The standby can survive a PostgreSQL process crash, but its WAL need not survive an OS crash. Local primary flush is also required.'),
 s('Тот же COMMIT в варианте on ждёт устойчивого сохранения WAL репликой.','The same COMMIT in the on alternative waits for durable standby WAL.',[primary(['local flush: 0/140']),replicaPositions('0/140','0/140','0/100'),app(['on: OK'])],[f('positions','primary','flush ack','sync'),f('primary','app','OK','reply')],`-- Alternative run from the same initial state: balance = 100.
-- LSN 0/140 is illustrative; these are not consecutive commits.
BEGIN;
SET LOCAL synchronous_commit = 'on';
UPDATE replica_account SET balance = 80 WHERE id = 1;
COMMIT;`,'Это гарантия сохранности WAL выбранной синхронной standby, а не готовности её SELECT. Пока replay позади, новое чтение на ней ещё может вернуть старое значение.','This guarantees durable WAL on the selected synchronous standby, not readiness of its SELECT results. While replay lags, a new read there can still return an old value.'),
 s('Тот же COMMIT в варианте remote_apply ждёт применения WAL репликой.','The same COMMIT in the remote_apply alternative waits for standby replay.',[primary(['local flush: 0/140']),replicaPositions('0/140','0/140','0/140'),app(['remote_apply: OK'])],[f('positions','primary','replay ack','sync'),f('primary','app','OK','reply')],`-- Alternative run from the same initial state: balance = 100.
-- LSN 0/140 is illustrative; these are not consecutive commits.
BEGIN;
SET LOCAL synchronous_commit = 'remote_apply';
UPDATE replica_account SET balance = 80 WHERE id = 1;
COMMIT;`,'Новые снимки на участвовавших в ожидании standby могут видеть транзакцию. Это не распространяется на произвольную другую реплику и не обновляет снимок уже начатой Repeatable Read-транзакции.','New snapshots on the standbys involved in the wait can see the transaction. This does not cover an arbitrary other replica or refresh an existing Repeatable Read snapshot.'),
 s('Чем дальше точка ожидания, тем больше задержка и зависимость от реплики.','A later acknowledgment point adds latency and standby dependency.',[table('modes','Точки ожидания','Wait points',['mode','required stage'],[['off',b('без ожидания flush','no flush wait')],['local','primary flush'],['remote_write','standby write'],['on','standby flush'],['remote_apply','standby replay']]),status('availability','Доступность','Availability',[b('Нет нужных ack → ожидание','Missing required ack → wait')])],[],'','Если требуемые синхронные участники недоступны, записывающий COMMIT может ждать. off допускает потерю недавних подтверждённых транзакций при сбое; это не то же самое, что отключать fsync. В отличие от показанных UPDATE, read-only COMMIT такого ожидания не требует.','If required synchronous participants are unavailable, a writing COMMIT can wait. off permits losing recent acknowledged transactions on a crash; it differs from disabling fsync. Unlike the UPDATE examples, a read-only COMMIT does not require that standby wait.')
]}),
c({number:66,id:'app-routing',group:9,title:['Куда приложению отправлять запрос','Where an application sends queries'],question:['Почему нельзя просто раздать все SELECT по репликам?','Why cannot every SELECT simply go to a replica?'],next:['Что удерживает WAL и старые версии для отставшей реплики?','What retains WAL and row versions for a lagging standby?'],docs:['libpq-connect.html#LIBPQ-CONNECT-TARGET-SESSION-ATTRS','hot-standby.html','warm-standby.html#SYNCHRONOUS-REPLICATION'],book:[],steps:[
 s('Приложение имеет отдельные пути к primary и реплике.','The application has separate paths to primary and standby.',[app(['write / fresh read','stale-tolerant read']),primary(['read + write']),standby(['read only'])],[f('app','primary','write path','request'),f('app','standby','read path','request')],`SELECT pg_is_in_recovery();
SHOW transaction_read_only;`,'Физическая hot standby принимает чтения с ограничениями. Путь записи нужен также для SELECT FOR UPDATE, DDL и операций, которые меняют состояние, например nextval().','A physical hot standby serves reads with restrictions. The write path is also needed for SELECT FOR UPDATE, DDL, and state-changing operations such as nextval().'),
 s('Запись уже подтверждена, но немедленное чтение реплики даёт старые данные.','The write is acknowledged, but an immediate standby read returns old data.',[app(['save 80 → read 100']),primary(['balance = 80']),standby(['balance = 100'])],[f('app','primary','UPDATE / COMMIT','request'),f('primary','app','OK','reply'),f('app','standby','SELECT','request')],'','Так возникает типичное нарушение ожидаемого read-your-writes при асинхронной репликации. Успех записи на primary не определяет replay-позицию выбранной для чтения standby.','Asynchronous replication can violate an application’s expected read-your-writes behavior. A primary write acknowledgment does not determine replay progress on the standby chosen for the read.'),
 s('Чтение, которому нужна свежая запись, направляем на primary.','Send a read requiring the recent write to the primary.',[app(['save 80 → read 80']),primary(['balance = 80']),standby(['balance = 100'])],[f('app','primary','fresh SELECT','request'),f('primary','app','80','reply')],'','Здесь выбран простой контракт приложения: критичное чтение идёт на primary. Отчёты с допустимым отставанием могут использовать отдельный пул реплик. Классификация зависит от требований запроса, а не от одного слова SELECT.','This example chooses a simple application contract: critical reads go to the primary. Reports that tolerate lag can use a standby pool. Classification depends on query requirements, not merely the SELECT keyword.'),
 s('Все команды одной транзакции остаются на одном соединении.','Keep all statements of a transaction on one connection.',[app(['one connection']),primary(['BEGIN → UPDATE','SELECT → COMMIT']),standby(['not this transaction'])],[f('app','primary','BEGIN','request'),f('primary','app','transaction result','reply')],`BEGIN;
UPDATE replica_account SET balance = balance - 10 WHERE id = 1;
SELECT balance FROM replica_account WHERE id = 1;
COMMIT;`,'Чтение внутри этой транзакции должно видеть её собственную запись. Переносить отдельный SELECT на другую базовую сессию нельзя: это другая транзакция с другим снимком.','The transaction’s read must see its own write. Moving that SELECT to another database session would use a different transaction and snapshot.'),
 s('libpq может выбрать сервер нужной роли при подключении.','libpq can select a server with the required role at connection time.',[app(['host = p1,p2','target_session_attrs','read-write']),primary(['acceptable']),standby(['reject for write path'])],[f('app','standby','check session','request'),f('app','primary','connect','request')],'','Строка подключения host=p1,p2 target_session_attrs=read-write выбирает сессию, разрешающую запись по умолчанию. Для чтений есть standby и prefer-standby. Это возможности libpq; другие драйверы надо проверять отдельно.','The connection string host=p1,p2 target_session_attrs=read-write selects a session accepting writes by default. Read paths can use standby or prefer-standby. These are libpq features; other drivers need their own checks.'),
 s('Выбор сервера не повторяется перед каждым запросом.','Server selection is not repeated before every query.',[app(['connected to p1']),primary(['all session queries']),box('reconnect','После обрыва','After disconnect',[b('Новое соединение','New connection'),b('Исход COMMIT может быть неизвестен','COMMIT outcome may be unknown')])],[f('app','primary','session queries','request')],'','load_balance_hosts=random распределяет новые подключения, а не команды внутри соединения. После обрыва приложение переподключается и разбирает исход операции; безусловный повтор записи может дублировать эффект.','load_balance_hosts=random spreads new connections, not queries within an established connection. After a disconnect the application reconnects and resolves the operation outcome; blindly retrying a write can duplicate its effect.')
]}),
c({number:67,id:'replication-retention',group:9,title:['Отставание, слоты и конфликт VACUUM','Lag, slots and VACUUM conflicts'],question:['Почему медленная реплика может увеличивать диск primary?','Why can a slow standby increase primary disk usage?'],next:['Как безопасно сделать реплику ведущей?','How can a standby safely become primary?'],docs:['warm-standby.html#STREAMING-REPLICATION-SLOTS','hot-standby.html#HOT-STANDBY-CONFLICT','runtime-config-replication.html','view-pg-replication-slots.html'],book:[],steps:[
 s('Отключённой реплике ещё нужен старый WAL.','A disconnected standby still needs old WAL.',[primary(['current WAL: 0/900']),wal(['0/100','0/500','0/900']),standby(['offline','needs from 0/100'])],[f('primary','wal','generate more WAL','internal')],'','WAL постоянно растёт логически, а старые сегменты могут переиспользоваться. Если нужные сегменты уже исчезли и нет архива, отставшая standby может потребовать новую базовую копию.','WAL grows logically while old segments can be recycled. If required segments are gone and no archive supplies them, the lagging standby may need a new base backup.'),
 s('Replication slot удерживает нужную для потребителя историю.','A replication slot retains the history its consumer still needs.',[primary(['slot: standby_a']),wal(['retain from 0/100','...','current 0/900']),standby(['offline'])],[f('primary','wal','retain WAL','internal')],`SELECT slot_name, slot_type, active, restart_lsn
FROM pg_replication_slots;`,'restart_lsn показывает старейшую позицию WAL, которая ещё может понадобиться слоту. Слот — механизм удержания, а не копия данных и не гарантия доступности реплики.','restart_lsn identifies the oldest WAL position the slot might still need. A slot is a retention mechanism, not a data copy or an availability guarantee.'),
 s('Пока реплика не продвигается, удержанный WAL занимает больше места.','While the standby stalls, retained WAL consumes more space.',[wal(['retained WAL grows','0/100 … 0/F00']),status('disk','Диск primary','Primary disk',[b('Свободное место убывает','Free space decreases')]),standby(['still offline'])],[f('wal','disk','retain segments','internal')],`SELECT slot_name, wal_status, safe_wal_size FROM pg_replication_slots;`,'Нужно следить за удержанным объёмом, свободным диском и состоянием слота. max_slot_wal_keep_size ограничивает удержание: при утрате требуемого WAL слот уже не сможет продолжить прежний поток.','Monitor retained bytes, free disk and slot status. max_slot_wal_keep_size bounds retention; if required WAL is lost, the slot cannot continue its previous stream.'),
 s('Долгий SELECT на standby может мешать применению очистки.','A long standby SELECT can conflict with replaying cleanup.',[primary(['VACUUM removed v1']),wal(['cleanup page 4']),standby(['old snapshot needs v1'])],[f('primary','wal','cleanup WAL','internal'),f('wal','standby','replay conflict','wait')],'','VACUUM на primary уже выполнил очистку. При replay standby не может просто отменить это решение: ей надо либо подождать завершения конфликтующего чтения, либо отменить его.','Primary VACUUM has already performed cleanup. During replay, the standby cannot simply undo that decision; it must wait for the conflicting reader or cancel it.'),
 s('Лимит ожидания защищает replay ценой отмены запроса.','The delay limit protects replay by canceling a conflicting query.',[standby(['SELECT canceled']),wal(['cleanup replayed']),status('error','Ошибка чтения','Read error',[b('Конфликт с восстановлением','Recovery conflict')])],[f('standby','error','cancel query','reply'),f('wal','standby','continue replay','sync')],`SELECT * FROM pg_stat_database_conflicts;`,'max_standby_streaming_delay ограничивает задержку применения полученного WAL, а не выдаёт каждому запросу отдельное полное время жизни. Повтор чтения может пройти, но его надо начать в новой транзакции.','max_standby_streaming_delay limits delay in applying received WAL; it is not a fresh full lifetime budget for each query. A retry may succeed, but it needs a new transaction.'),
 s('hot_standby_feedback защищает старые версии, задерживая очистку primary.','hot_standby_feedback protects old versions by delaying primary cleanup.',[standby(['snapshot horizon']),primary(['keep needed versions']),table('versions','Версии в heap primary','Primary heap versions',['version','state'],[['v1',b('нужна standby','needed by standby')],['v2',b('текущая','current')]])],[f('standby','primary','xmin feedback','sync'),f('primary','versions','retain old tuple','internal')],'','Это уменьшает конфликты очистки, но способно вызвать bloat на primary. Обратная связь не устраняет все виды конфликтов, например конфликт с DROP TABLE. Для защиты при отключении важна также конфигурация слота.','Feedback reduces cleanup conflicts but can cause primary bloat. It does not remove every conflict, such as DROP TABLE conflicts. Protection across disconnection also depends on slot configuration.')
]}),
c({number:68,id:'failover',group:9,title:['Failover, fencing и новый primary','Failover, fencing and a new primary'],question:['Как избежать двух ведущих после сетевого сбоя?','How can failover avoid two primaries after a network fault?'],next:['Как реплицировать выбранные таблицы вместо целого кластера?','How can selected tables replicate instead of the whole cluster?'],docs:['warm-standby-failover.html','warm-standby.html','app-pgrewind.html','functions-admin.html'],book:[],steps:[
 s('Primary недоступен приложению; standby ещё отвечает.','The application cannot reach the primary, while the standby responds.',[app(['connection lost']),primary(['unreachable']),standby(['read only'])],[f('app','primary','timeout','wait')],'','Недоступность по сети сама по себе не доказывает, что primary выключен. Он может продолжать обслуживать клиентов с другой стороны разделения сети.','Network unreachability does not prove the primary is stopped. It may still serve clients on the other side of a network partition.'),
 s('Решение о переключении принимает оператор или внешняя система.','An operator or external system decides whether to fail over.',[primary(['unreachable']),standby(['candidate']),box('manager','Внешний координатор','External coordinator',[b('Проверка доступности','Availability check'),b('Выбор кандидата','Candidate choice')])],[f('manager','standby','inspect candidate','request')],'','Ядро PostgreSQL не предоставляет автоматическую систему обнаружения отказа и выборов лидера. На схеме координатор явно находится за пределами сервера базы.','PostgreSQL core does not provide the automatic failure-detection and leader-election system. The coordinator is explicitly outside the database server.'),
 s('Прежний primary изолируют от новых записей.','Fence the old primary off from new writes.',[primary(['writes blocked']),standby(['candidate']),box('manager','Внешний координатор','External coordinator',['fencing complete'])],[f('manager','primary','fence','request')],'','Fencing должен реально исключить возможность записи на старый primary, а не просто скрыть его в одном клиентском списке. Иначе после promotion получится split-brain с расходящимися историями.','Fencing must actually prevent writes to the old primary, not merely hide it from one client list. Otherwise promotion can create split-brain with divergent histories.'),
 s('Выбранная standby завершает доступное восстановление и повышается.','The chosen standby finishes available recovery and is promoted.',[standby(['promoting → primary']),wal(['available WAL replayed']),box('manager','Внешний координатор','External coordinator',['promote selected node'])],[f('manager','standby','pg_promote()','request'),f('wal','standby','finish recovery','sync')],`SELECT pg_promote();`,'Команда выполняется на выбранной standby. При асинхронной схеме у неё может не оказаться всех ранее подтверждённых записей primary. Promotion не доставляет потерянный WAL из ниоткуда.','Run this on the chosen standby. Under asynchronous replication it may lack some previously acknowledged primary writes. Promotion cannot conjure up missing WAL.'),
 s('Приложение переподключается к новому ведущему узлу.','The application reconnects to the new primary.',[app(['new connection']),primary(['fenced']),standby(['new primary','read + write'])],[f('app','standby','connect / verify role','request'),f('standby','app','read-write session','reply')],`SELECT pg_is_in_recovery();`,'На новом primary функция теперь возвращает false. Смена роли не переносит активную сессию со старого сервера; приложение или слой маршрутизации должны восстановить подключение.','On the new primary the function now returns false. A role change does not migrate an active session from the old server; the application or routing layer must reconnect.'),
 s('Старый primary не возвращают в запись с прежней историей.','Do not return the old primary to writes with its divergent history.',[primary(['former primary','rebuild / pg_rewind']),standby(['current primary']),wal(['new timeline'])],[f('standby','primary','resynchronize','sync')],'','Бывший primary возвращают как standby после проверки и синхронизации. pg_rewind может ускорить это при выполнении требований; иногда нужна новая базовая копия. Самовольный запуск двух историй опасен.','The former primary returns as a standby after checks and resynchronization. pg_rewind can help when its requirements are met; otherwise a new base backup may be needed. Independently restarting both histories is unsafe.'),
 s('Новый primary снова получает standby; аварийную схему надо проверять заранее.','Rebuild standby protection for the new primary and test failover beforehand.',[primary(['now standby']),standby(['current primary']),app(['write path restored'])],[f('standby','primary','WAL stream','sync'),f('app','standby','normal traffic','request')],'','После promotion без новой реплики система остаётся без прежнего резерва. Switchover — плановая смена ролей; failover — реакция на отказ. Обе процедуры требуют проверенной маршрутизации и исключения split-brain.','After promotion, the system lacks its former redundancy until another standby is ready. Switchover is planned role change; failover responds to failure. Both need verified routing and split-brain prevention.')
]}),
c({number:69,id:'logical-replication',group:9,title:['Логическая публикация и подписка','Logical publication and subscription'],question:['Как переносить изменения выбранных таблиц?','How can changes in selected tables be replicated?'],next:['Дают ли встречные подписки прозрачный multi-master?','Do two-way subscriptions provide transparent multi-master?'],docs:['logical-replication.html','logical-replication-publication.html','logical-replication-subscription.html','logical-replication-restrictions.html','logical-replication-architecture.html'],book:[],steps:[
 s('Publisher и subscriber — две самостоятельные базы.','Publisher and subscriber are two independent databases.',[primary(['publisher: shop']),standby(['subscriber: analytics'])],[],`CREATE TABLE published_items (id int PRIMARY KEY, price int);
INSERT INTO published_items VALUES (1,100);`,'В этой главе подписи означают роли publisher/subscriber, а не физическую standby в recovery. Логическая подписка переносит изменения объектов и не копирует кластер побайтно.','Here the roles are publisher/subscriber, not a physical standby in recovery. A logical subscription transfers object changes rather than copying an entire cluster byte for byte.'),
 s('Публикация выбирает таблицу, а подписка связывает базы.','A publication selects a table; a subscription connects the databases.',[primary(['publication: items_pub']),box('subscription','Подписка items_sub','Subscription items_sub',['published_items']),standby(['same table schema'])],[f('standby','subscription','subscribe','request'),f('subscription','primary','publication','request')],`-- On the publisher:
CREATE PUBLICATION items_pub FOR TABLE published_items;
-- On the subscriber, after creating the matching table:
CREATE SUBSCRIPTION items_sub
CONNECTION 'host=publisher dbname=shop'
PUBLICATION items_pub;`,'Пример предполагает настроенные wal_level, права и доступ. Схему таблицы надо создать на subscriber отдельно; подписка не заменяет миграции DDL. CONNECTION здесь показывает форму, а не готовые реквизиты.','This example assumes suitable wal_level, permissions and connectivity. Create the subscriber table schema separately; subscriptions do not replace DDL migrations. CONNECTION illustrates syntax, not working credentials.'),
 s('Первичная синхронизация копирует строки согласованного снимка.','Initial synchronization copies rows from a consistent snapshot.',[primary(['snapshot: id 1 = 100']),queue('copy','Первичная копия','Initial copy',['(1,100)']),standby(['copying'])],[f('primary','copy','snapshot rows','sync'),f('copy','standby','COPY data','sync')],'','Изменения после снимка не должны пропасть: затем подписка догоняет поток изменений. Детали параллельной синхронизации таблиц скрыты, но граница «снимок плюс изменения» сохранена.','Changes after the snapshot must not disappear: the subscription catches up with subsequent changes. Parallel table synchronization details are omitted, while the snapshot-plus-changes boundary remains explicit.'),
 s('Логическое декодирование превращает WAL в изменения строк.','Logical decoding turns WAL into row changes.',[primary(['UPDATE id 1: 120']),wal(['physical WAL']),queue('changes','Логические изменения','Logical changes',['UPDATE id 1 → 120','COMMIT'])],[f('primary','wal','WAL','internal'),f('wal','changes','decode','internal')],`UPDATE published_items SET price = 120 WHERE id = 1;`,'Передаваемое изменение связано с таблицей и replica identity, обычно первичным ключом. Для UPDATE и DELETE нужна достаточная идентификация старой строки. Это не повтор исходного SQL-текста приложения.','A transmitted change identifies its table and replica identity, usually a primary key. UPDATE and DELETE need enough information to identify the old row. This is not a replay of the application’s original SQL text.'),
 s('Apply worker находит id 1 и применяет цену 120.','The apply worker finds id 1 and applies price 120.',[queue('changes','Изменения','Changes',['id 1 → 120']),standby(['apply worker']),table('replica','published_items','published_items',['id','price'],[['1','120']])],[f('changes','standby','apply','sync'),f('standby','replica','UPDATE','internal')],'','Порядок применения сохраняет транзакционную согласованность публикаций внутри одной подписки. Для независимых подписок нельзя автоматически обещать единый общий снимок или глобальный порядок.','Apply order preserves transactional consistency for publications within one subscription. Independent subscriptions do not automatically provide a shared global snapshot or ordering.'),
 s('DDL и состояние sequence не входят в обычный поток подписки.','DDL and sequence state are outside the ordinary subscription stream.',[primary(['ALTER TABLE','nextval(sequence)']),standby(['needs coordinated DDL','sequence not advanced']),box('uses','Где полезно','Useful cases',[b('Подмножество таблиц','Selected tables'),b('Между major-версиями','Across major versions')])],[],'','Значения serial/identity-столбца приходят вместе со строками, но сам счётчик sequence не синхронизируется. При переходе на subscriber как на писателя это надо учесть отдельно. Логическая репликация допускает разные major-версии.','Serial/identity column values replicate with their rows, but the sequence counter itself is not synchronized. A subscriber becoming a writer needs separate handling. Logical replication can cross major versions.')
]}),
c({number:70,id:'multiple-writers',group:9,title:['Несколько писателей и конфликты','Multiple writers and conflicts'],question:['Что произойдёт, если одинаковый ключ записан на двух узлах?','What happens when two nodes write the same key?'],next:['Теперь можно проследить запрос от приложения до страниц, WAL и реплик.','Now trace a query from the application to pages, WAL and replicas.'],docs:['logical-replication.html','logical-replication-conflicts.html','logical-replication-restrictions.html','sql-createsubscription.html','warm-standby-failover.html'],book:[],steps:[
 s('Две логические базы могут принимать локальные записи.','Two logically replicated databases can accept local writes.',[server('a','Узел A','Node A',['publisher + subscriber']),server('b','Узел B','Node B',['publisher + subscriber'])],[f('a','b','logical changes','sync'),f('b','a','logical changes','sync')],'','В отличие от физической standby, логический subscriber — обычная база. Возможность писать с двух сторон не задаёт автоматически правила совместного изменения данных.','Unlike a physical standby, a logical subscriber is an ordinary database. Allowing writes on both sides does not automatically define a safe concurrent-write protocol.'),
 s('Оба узла независимо создают строку с id 7.','Both nodes independently create a row with id 7.',[table('a','Данные A','A data',['id','value'],[['7','red']]),table('b','Данные B','B data',['id','value'],[['7','blue']])],[],`-- Independently on node A:
CREATE TABLE shared_items (id int PRIMARY KEY, value text);
INSERT INTO shared_items VALUES (7,'red');
-- Independently on node B, with the same table already created:
INSERT INTO shared_items VALUES (7,'blue');`,'Это два разных локально допустимых решения. При настройке двунаправленной топологии также надо предотвращать повторную отправку уже пришедших изменений; origin-фильтрация сама не разрешает конфликт ключей.','Each write is locally valid. A two-way topology must also avoid sending received changes around a loop; origin filtering alone does not resolve key conflicts.'),
 s('Входящий INSERT с A конфликтует с первичным ключом на B.','The INSERT arriving from A conflicts with B’s primary key.',[table('a','Данные A','A data',['id','value'],[['7','red']]),table('b','Данные B','B data',['id','value'],[['7','blue']]),status('conflict','Конфликт применения','Apply conflict',['insert_exists','PRIMARY KEY id 7'])],[f('a','b','INSERT (7, red)','sync'),f('b','conflict','unique violation','reply')],'','Нарушение ограничения при применении логической репликации останавливает apply до разрешения проблемы. Два узла не обязаны автоматически выбрать одно значение и сойтись.','A constraint violation during logical replication stops apply until the problem is resolved. The two nodes do not automatically choose a common value and converge.'),
 s('Нужны диагностика и явное решение о правильных данных.','Diagnose the conflict and explicitly decide the correct data.',[status('conflict','Остановленный apply','Stopped apply',['id 7: red vs blue']),box('decision','Решение владельца данных','Data-owner decision',[b('Исправить данные','Correct data'),b('Или осознанно пропустить','Or deliberately skip')]),queue('pending','Не применено','Not applied',['conflicting transaction','later transactions'])],[f('conflict','decision','inspect logs','request')],`SELECT * FROM pg_stat_subscription_stats;`,'Варианты зависят от смысла данных: устранить конфликт на subscriber либо осознанно пропустить проблемную транзакцию. Пропуск может потерять и другие её изменения, поэтому это не универсальная кнопка «починить».','The right action depends on data meaning: remove the subscriber conflict or deliberately skip the offending transaction. Skipping can lose its other changes too, so it is not a universal repair button.'),
 s('Разделение владения данными уменьшает риск встречных записей.','Separating data ownership reduces conflicting writes.',[table('a','Владелец tenant 1','Owner of tenant 1',['tenant','writer'],[['1','A']]),table('b','Владелец tenant 2','Owner of tenant 2',['tenant','writer'],[['2','B']]),box('contract','Правило приложения','Application rule',[b('Один владелец каждой записи','One owner per record')])],[f('contract','a','tenant 1 writes','request'),f('contract','b','tenant 2 writes','request')],'','Это пример архитектурного правила, а не встроенная автоматическая гарантия Postgres. Даже при разных диапазонах ключей надо продумать удаления, внешние ключи, DDL, sequence и поведение при разделении сети.','This is an application architecture rule, not an automatic Postgres guarantee. Even disjoint key ranges require thinking through deletes, foreign keys, DDL, sequences and network partitions.'),
 s('Базовая модель — один ведущий; multi-writer требует отдельного протокола.','The baseline is one primary; multi-writer requires an additional protocol.',[box('physical','Физическая схема','Physical topology',[b('Один писатель','One writer'),b('Standby читает и replay WAL','Standby reads and replays')]),box('logical','Логическая схема','Logical topology',[b('Независимые базы','Independent databases'),b('Нужна политика конфликтов','Conflict policy required')]),app([b('Согласованный путь записи','Defined write path')])],[],'','Встроенные физическая и логическая репликации решают разные задачи. Из них нельзя вывести обещание прозрачного multi-master с автоматическими выборами и разрешением любых конфликтов. Для приложения сначала определяют владельца записи и гарантии чтения.','Built-in physical and logical replication solve different problems. Neither implies transparent multi-master with automatic elections and resolution of arbitrary conflicts. An application must first define write ownership and read guarantees.')
]})
];
